try{ 
var currency = sforce.connection.query( "SELECT Conversion_Rate__c FROM Product_PriceList__c limit 1"); 
var records = currency.getArray("records"); 
//var newRecords = []; 
var synccur = new sforce.SObject("apttus_proposal_proposal__c"); 
synccur.id = '{!apttus_proposal_proposal__c.Id}'; 

synccur.Conversion_Rate__c = records[0].Conversion_Rate__c; 

//newRecords.push(synccur); 
result = sforce.connection.update([synccur]); 
window.location.reload(); 
} 
catch(error){ 
Alert('An Error has Occurred. Error: ' + error); 
}
